import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"会话上下文压缩","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/compaction.md","filePath":"zh/guides/compaction.md","lastUpdated":1790952322000}'),n={name:"zh/guides/compaction.md"};function d(s,t,i,l,c,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="会话上下文压缩" tabindex="-1">会话上下文压缩 <a class="header-anchor" href="#会话上下文压缩" aria-label="Permalink to &quot;会话上下文压缩&quot;">​</a></h1><p><strong>上下文压缩</strong>只针对<strong>当前这一会话</strong>：把早先轮次压成摘要，让后面模型调用时带的<strong>活跃窗口</strong>小一点。</p><p>这和<strong>改记忆库里存的长记忆</strong>不是一码事。要动存储条目，看 <a href="./memory.html">长期记忆</a>。</p><hr><h2 id="现在默认就开着-零配置" tabindex="-1">现在默认就开着，零配置 <a class="header-anchor" href="#现在默认就开着-零配置" aria-label="Permalink to &quot;现在默认就开着，零配置&quot;">​</a></h2><p>新建的 Bot 自动压缩<strong>默认启用</strong>，阈值、比例、摘要模型一个都不用配——Memoh 全按聊天模型的 <code>context_window</code> 比例来：</p><ul><li>会话可压缩历史超过窗口约 <strong>50%</strong>：本轮结束后<strong>后台</strong>压。</li><li>后台没追上、涨过约 <strong>75%</strong>：下一轮发送前<strong>同步</strong>压。</li><li>两条路都把原始历史压回窗口约 <strong>40%</strong>。</li></ul><p>唯一的真前提：聊天模型必须在模型设置里声明 <code>context_window</code>。没有它，自动策略没有预算基准，<strong>永远不会触发</strong>。见 <a href="./../integrations/providers/llm.html">模型服务商与模型</a>。</p><p>默认值变更之前建的 Bot 保留原有设置、按原语义跑（见下面的 legacy 模式）。</p><hr><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><p>要调也还是可以调：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>默认开。关掉即禁用本 Bot 的自动压缩。</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>输入 token 阈值。<code>0</code>（默认）= 上面的自动比例策略；<strong>大于 0</strong> 切到 legacy 绝对阈值模式。</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>压多狠。只在 legacy 模式下生效——阈值为 <code>0</code> 时这个字段直接隐藏。</td></tr><tr><td><strong>Compaction Model</strong></td><td>可选的专用摘要模型。默认继承聊天模型；设过 override 也可以清回 <strong>Use chat model (default)</strong>。</td></tr></tbody></table><h3 id="摘要模型怎么选" tabindex="-1">摘要模型怎么选 <a class="header-anchor" href="#摘要模型怎么选" aria-label="Permalink to &quot;摘要模型怎么选&quot;">​</a></h3><p>启用的 chat 模型基本都行，唯一限制：provider 必须尊重输出 token 上限。<strong>OpenAI Codex 系模型当不了摘要模型</strong>——下拉框里直接筛掉了。</p><p>要注意的场景：Bot 主聊天模型本身就是 Codex 时，自动压缩因为没有可继承的合法模型会<strong>静默不跑</strong>。这种情况显式配一个 Compaction Model。</p><hr><h2 id="立刻压" tabindex="-1">立刻压 <a class="header-anchor" href="#立刻压" aria-label="Permalink to &quot;立刻压&quot;">​</a></h2><p>两路：</p><h3 id="状态区" tabindex="-1">状态区 <a class="header-anchor" href="#状态区" aria-label="Permalink to &quot;状态区&quot;">​</a></h3><ol><li>打开当前对话。</li><li>打开会话状态区。</li><li>点 <strong>Compact Now</strong>。</li></ol><p>上面也有上下文占用、缓存、技能等，方便你判断要不要现在压。</p><h3 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>或</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact run</span></span></code></pre></div><p>手动压缩会尽量<strong>全量</strong>压（不止压到自动目标线），并且绕过自动压缩失败后的短冷却。</p><hr><h2 id="压缩保真度" tabindex="-1">压缩保真度 <a class="header-anchor" href="#压缩保真度" aria-label="Permalink to &quot;压缩保真度&quot;">​</a></h2><p>摘要器现在按类型化的会话记录工作，几个对质量有实际影响的行为：</p><ul><li>工具调用和结果<strong>永不拆开</strong>——一次 tool 交互要么整体留在原始历史、要么整体进摘要。</li><li>媒体降级为 <code>[image]</code> / <code>[file]</code> 标记，不塞原始数据。</li><li>空的、被截断的、压完不比原文小的摘要直接拒收，不会存成结果。</li><li>跨多个 workspace 的会话里，摘要保留&quot;哪段话在哪台机器上发生&quot;的信息。</li></ul><p>普通 chat、<strong>discuss</strong>、pipeline 类对话都会压。</p><hr><h2 id="记录" tabindex="-1">记录 <a class="header-anchor" href="#记录" aria-label="Permalink to &quot;记录&quot;">​</a></h2><p>Bot 详情 <strong>Compaction</strong> tab 可看各次：成功/失败、摘要或预览、涉多少条消息、起止时间、若有的模型与用量。用来确认<strong>自动</strong>有没有在跑、失败原因等。</p><h3 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to &quot;常见失败原因&quot;">​</a></h3><p>跑不了时报 <code>compaction.model_unavailable</code> 并带具体原因：摘要模型未配置、不是 chat 模型、被禁用、provider 被禁用、provider 不支持输出上限（Codex）、模型没有已知 context window。<code>/compact</code> 在聊天里报同样的状态。</p><hr><h2 id="与-context-window-的关系" tabindex="-1">与 <code>context_window</code> 的关系 <a class="header-anchor" href="#与-context-window-的关系" aria-label="Permalink to &quot;与 `context_window` 的关系&quot;">​</a></h2><p>Memoh 拿当前 chat 模型的 <code>context_window</code> 对照本会话，网页状态区、<code>/status</code> 都能看到离上限多近。注意 token 是粗估（约 4 字符/token），百分比当参考就好，别当精确值。</p><hr><h2 id="和「记忆压缩」的区别" tabindex="-1">和「记忆压缩」的区别 <a class="header-anchor" href="#和「记忆压缩」的区别" aria-label="Permalink to &quot;和「记忆压缩」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>作用范围</th><th>怎么触发</th><th>结果</th></tr></thead><tbody><tr><td><strong>上下文压缩</strong></td><td>当前活跃会话</td><td>自动 / 状态区 / <code>/compact</code></td><td>本会话里较早内容变摘要，方便后面几轮继续聊</td></tr><tr><td><strong>记忆压缩</strong></td><td>长期记忆提供方</td><td>Memory tab</td><td>改库里记忆条目，不是单会话 prompt</td></tr></tbody></table><p><strong>一路聊太长了</strong> → 上下文压缩。<br><strong>存下来的记忆又脏又重</strong> → 去 Memory 里做那类维护。</p><hr><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>会话、Discuss：<a href="./sessions.html">会话</a></li><li>斜杠与 <code>/compact</code>：<a href="./slash-commands.html">斜杠命令</a></li><li>长期记忆维护：<a href="./memory.html">长期记忆</a></li></ul>',47)])])}const m=o(n,[["render",d]]);export{g as __pageData,m as default};
